schema_ddl:
CREATE TABLE chiamate (
    id_chiamata BIGINT PRIMARY KEY,
    numero_mittente TEXT NOT NULL,
    numero_destinatario TEXT NOT NULL,
    data_ora TIMESTAMP NOT NULL,
    durata_secondi INT NOT NULL CHECK (durata_secondi >= 0),
    tipo_chiamata TEXT NOT NULL CHECK (tipo_chiamata IN ('voce', 'video', 'internazionale', 'roaming')),
    stato_chiamata TEXT NOT NULL DEFAULT 'completata' CHECK (stato_chiamata IN ('completata', 'persa', 'inoltrata'))
);

CREATE INDEX idx_chiamate_mittente ON chiamate (numero_mittente);

CREATE INDEX idx_chiamate_data_ora ON chiamate (data_ora);
